const d = $input.first().json;
const img = d.image || 'unknown';
const ctr = (d.metadata && d.metadata.container_name) || img.split(':')[0].split('/').pop();
const hub = d.hub_link || 'https://hub.docker.com';
const svc = ctr.replace('cryptex-', '');

const prompt = `You are a server maintenance assistant for a self-hosted Docker homelab. A Docker image update is available.

Image: ${img}
Container: ${ctr}
Hub link: ${hub}

Provide a brief update analysis (max 120 words, plain text, no markdown formatting):
1. Update type: major / minor / patch
2. Key changes (2-3 specific points)
3. Security fixes? yes/no (include CVE IDs if known)
4. Breaking changes? yes/no (details if yes)
5. Verdict: SAFE ✅ / CAUTION ⚠️ / SKIP ❌`;

return [{ json: { prompt, image: img, container: ctr, service: svc, hub } }];

const gemRes = $input.first().json;
const prev = $('Build Gemini Prompt').first().json;

let analysis = 'Analysis unavailable (Gemini API error)';
try {
  analysis = gemRes.candidates[0].content.parts[0].text.trim();
} catch(e) {}

const updateCmd = `docker compose pull ${prev.service} && docker compose up -d --no-deps --force-recreate ${prev.service}`;

const msg = `\ud83d\udd14 Docker Update Available\n\n\ud83d\udce6 Image: ${prev.image}\n\ud83d\udc33 Container: ${prev.container}\n\n\ud83e\udd16 Gemini Analysis:\n${analysis}\n\n──────────────────\nTo update (run in workstation):\n${updateCmd}`;

return [{ json: { message: msg } }];
